const SUPPORTED_LANGS = ['tr', 'en', 'fr', 'de', 'es', 'it', 'ru', 'zh', 'ja', 'ko', 'ar', 'pt', 'nl', 'pl', 'hi', 'vi'];

// 1. Önce STRINGS_UI'daki tüm dilleri varsayılan olarak İngilizce ile doldur (Eğer yoksa)
SUPPORTED_LANGS.forEach(lang => {
  if (!STRINGS_UI[lang]) {
    // İngilizce verileri kopyala
    STRINGS_UI[lang] = JSON.parse(JSON.stringify(STRINGS_UI['en']));
    
    // Varsa kısmi çevirileri üzerine yaz
    if (PARTIAL_TRANSLATIONS[lang]) {
       STRINGS_UI[lang] = { ...STRINGS_UI[lang], ...PARTIAL_TRANSLATIONS[lang] };
    }
  }
});
